double I3m1a(double s1, double s2, double s3, double rtmdel) {
    using namespace constants_mod;

    double d1 = s1 - s2 - s3;
    double d2 = s2 - s3 - s1;
    double d3 = s3 - s1 - s2;

    double arg1 = 2 * std::atan(rtmdel / d1);
    double arg2 = 2 * std::atan(rtmdel / d2);
    double arg3 = 2 * std::atan(rtmdel / d3);
    return 2 / rtmdel * (dclaus(arg1) + dclaus(arg2) + dclaus(arg3));
}

std::complex<double> I3m1b(double s1, double s2, double s3, double rtdel, double flag) {
    using namespace constants_mod;

    std::complex<double> result;
    double d3 = s3 - s1 - s2;
