    double y = s2 / s3;
    double rat = 0.5 * (d3 + rtdel) / s3;

    if (std::abs(rat) < 1.e-3) rat = 2.0 * s1 * s2 / (s3 * (d3 - rtdel));
    double rho = 1.0 / rat;
    double argx = rho * x;
    double argy = rho * y;
    double argdlx = -argx;
    double argdly = -argy;

    if ((argdlx > 1.0) || (argdly > 1.0)) {
