        / (zb(j1, j2) * zb(j2, j3) * zb(j5, j6) * za(j1, j3)
             * t(j1, j2, j3) * zab2(j1, j2, j3, j4));

  return FMPFsc_unsym_value;
}

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
