std::complex<double> FMPFsc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  std::complex<double> FMPFsc_value =
      FMPFsc_unsym(j1, j2, j3, j4, j5, j6, za, zb)
      + FMPFsc_unsym(j4, j3, j2, j1, j6, j5, zb, za);

  return FMPFsc_value;
}

